  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Creates a new IPO application for a retail customer.
   * The customer must provide a target company, a share count greater than 0, a payment amount greater than 0,
   * and a non-null allowance document.
   * The system only creates the application when the customer is currently eligible to apply and has no approved
   * application for the same company name.
   * Algorithm:
   * 1. Validate inputs:
   *    - company is not null
   *    - shares > 0
   *    - amount > 0
   *    - doc is not null
   *    - doc.name is not null/empty
   * 2. Check customer.isEligibleForIPO() == true.
   * 3. Check that there is no existing APPROVAL application in applications for the same company.name.
   * 4. If any validation fails, return false.
   * 5. Create a new Application with:
   *    - company = company
   *    - share = shares
   *    - amountOfMoney = amount
   *    - allowance = doc
   *    - customer = this
   *    - status = PENDING
   * 6. Add the new Application to applications.
   * 7. Return true.
   * Related Features:
   * - applications
   * - canApplyForIPO
   * - createApplication(company : Company, shares : int, amount : double, doc : Document)
   * - isEligibleForIPO()
   * Related Classes: Application, Company, Document, ApplicationStatus
   * Input:
   * - company : Company
   *   - Target company for the IPO application.
   *   - Must not be null.
   * - shares : int
   *   - Number of shares requested.
   *   - Must be greater than 0.
   * - amount : double
   *   - Paid amount for the application.
   *   - Must be greater than 0.
   * - doc : Document
   *   - Legal allowance document.
   *   - Must not be null.
   *   - doc.name should identify the document and must not be null/empty.
   * Output:
   * - boolean: true when the application record is created successfully; otherwise false.
   * Pre-condition:
   * - The customer is a retail customer eligible to apply for IPO.
   * - The provided company, shares, amount, and document are valid.
   * - No approved application already exists in the customer applications for the same company name.
   * Post-condition:
   * - If true:
   *   - a new pending Application is added to applications.
   *   - the new application references the provided customer, company, and document.
   * - If false:
   *   - applications remains unchanged.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean createApplication(final Company company, final int shares, final double amount, final Document doc)
  {
    if (company == null || shares <= 0 || amount <= 0 || doc == null || doc.getName() == null || doc.getName().isEmpty())
    {
      return false;
    }
    if (!isEligibleForIPO())
    {
      return false;
    }
    for (Application application : getApplications())
    {
      Company appCompany = application.getCompany();
      if (application.getStatus() == ApplicationStatus.APPROVAL && appCompany != null && company.getName() != null && company.getName().equals(appCompany.getName()))
      {
        return false;
      }
    }
    Application newApplication = IpoFactory.eINSTANCE.createApplication();
    newApplication.setCompany(company);
    newApplication.setShare(shares);
    newApplication.setAmountOfMoney(amount);
    newApplication.setAllowance(doc);
    newApplication.setCustomer(this);
    newApplication.setStatus(ApplicationStatus.PENDING);
    getApplications().add(newApplication);
    return true;
    
  }

